int replace_map_pointers(struct verifier_env *env) {
    int i;
    struct bpf_insn *insn;
    struct bpf_map *map;
    int err;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (insn->code != (BPF_LDX | BPF_IMM | BPF_DW) && insn->code != (BPF_STX | BPF_IMM | BPF_DW))
            continue;

        if (insn->src_reg != BPF_PSEUDO_MAP_FD)
            continue;

        if (i + 1 >= env->prog->len)
            return -EINVAL;

        map = bpf_map_get_from_fd(insn->off);
        if (IS_ERR_OR_NULL(map))
            return PTR_ERR(map);

        if (env->used_maps >= MAX_USED_MAPS) {
            bpf_map_put(map);
            return -EMFILE;
        }

        insn->off = (unsigned long)map;
        env->used_maps++;
        env->maps[env->used_maps - 1] = map;
    }

    return 0;
}

int replace_map_pointers(struct verifier_env *env) {
    struct bpf_insn *insn;
    struct bpf_map *map;
    int i, fd, err;
    u32 insn_idx;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];
        insn_idx = i;

        if (insn->code == (BPF_LDX | BPF_MEM)) {
            if (insn->off != 0)
                return -EINVAL;
        }

        if ((insn->code == (BPF_LD | BPF_IMM | BPF_DW)) &&
            (insn->src_reg == BPF_PSEUDO_MAP_FD)) {
            fd = insn->imm;
            map = find_map_by_fd(fd);
            if (!map)
                return -ENOENT;

            if (env->used_maps >= MAX_USED_MAPS)
                return -ENOMEM;

            insn->src_reg = 0;
            insn->off = 0;
            insn->imm = 0;

            insn = &env->prog->insnsi[i + 1];
            insn->code = (BPF_LDX | BPF_MEM);
            insn->dst_reg = BPF_REG_2;
            insn->src_reg = 0;
            insn->off = 0;
            insn->imm = (unsigned long)map;

            env->used_maps++;
            env->maps[env->used_maps - 1] = map;
            bpf_map_inc_ref(map);
        }
    }

    return 0;
}

int replace_map_pointers(struct verifier_env *env) {
    int i;
    struct bpf_insn *insn;
    struct bpf_map *map;
    int err;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (BPF_CLASS(insn->code) != BPF_LD && BPF_CLASS(insn->code) != BPF_LDX &&
            BPF_CLASS(insn->code) != BPF_ST && BPF_CLASS(insn->code) != BPF_STX)
            continue;

        if (insn->code == (BPF_LD | BPF_IMM | BPF_DW)) {
            if (!is_pseudo_map_fd(insn->src_reg))
                continue;

            map = get_bpf_map_from_fd(insn->imm);
            if (!map)
                return -ENOENT;

            if (env->used_maps_count >= MAX_USED_MAPS) {
                bpf_map_put(map);
                return -EBUSY;
            }

            insn->off = (u32)map;
            insn->imm = (u32)((u64)map >> 32);
            insn->src_reg = 0;  // No longer a pseudo fd
            insn->code = BPF_LDX | BPF_MEM | BPF_DW;

            env->used_maps[env->used_maps_count++] = map;
        } else {
            // For BPF_STX and similar, check reserved fields for misuse
            if (insn->off != 0 || insn->imm != 0)
                return -EINVAL;
        }
    }

    return 0;
}

int replace_map_pointers(struct verifier_env *env) {
    int i;
    struct bpf_insn *insn;
    struct bpf_map *map;
    int err;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (BPF_CLASS(insn->code) != BPF_LD && BPF_CLASS(insn->code) != BPF_LDX &&
            BPF_CLASS(insn->code) != BPF_ST && BPF_CLASS(insn->code) != BPF_STX)
            continue;

        if ((BPF_CLASS(insn->code) == BPF_LD || BPF_CLASS(insn->code) == BPF_LDX) &&
            BPF_MODE(insn->code) == BPF_IMM && BPF_SIZE(insn->code) == BPF_DW) {
            int fd = insn->off;

            if (fd < 0)
                return -EINVAL;

            map = find_map_from_fd(fd);
            if (!map)
                return -ENOENT;

            if (env->used_maps >= MAX_USED_MAPS)
                return -ENOMEM;

            insn->off = (unsigned long)map;
            env->prog->aux->maps[env->used_maps++] = map;
            bpf_map_inc_ref(map);
        } else if (BPF_CLASS(insn->code) == BPF_STX && insn->off == 0) {
            // Check reserved field for invalid usage
            if (insn->imm)
                return -EINVAL;
        }
    }

    return 0;
}

int replace_map_fds_with_pointers(struct verifier_env *env) {
    int i;
    struct bpf_insn *insn;
    struct bpf_map *map;
    int fd;

    for (i = 0; i < env->prog->len; i++) {
        insn = &env->prog->insnsi[i];

        if (BPF_CLASS(insn->code) != BPF_LDX && BPF_CLASS(insn->code) != BPF_STX) {
            continue;
        }

        if (BPF_MODE(insn->code) != BPF_MEM && BPF_MODE(insn->code) != BPF_XADD) {
            continue;
        }

        if (BPF_SIZE(insn->code) != BPF_DW) {
            continue;
        }

        if (insn->jt != 0 || insn->jf != 0) {
            return -EINVAL;
        }

        fd = insn->off;
        if (fd < 0 || fd >= MAX_MAPS) {
            return -EINVAL;
        }

        if (env->used_maps_count >= MAX_USED_MAPS) {
            return -ENOMEM;
        }

        map = find_bpf_map_by_fd(fd);
        if (!map) {
            return -ENOENT;
        }

        if (map->refcnt == 0) {
            return -EINVAL;
        }

        insn->off = (unsigned long)map;
        env->used_maps[env->used_maps_count++] = map;
        map->refcnt++;
    }

    return 0;
}
